@strawberry.type
class Mutation:
    @strawberry.mutation
    def update_profile_phone(self, info: Info, user_id: int, phone: str) -> ProfileResponse:
        db: Session = info.context["db"]
        current_user = info.context["user"]
        if user_id != current_user.id:
            return ProfileResponse(success=False, message="Cannot modify phone for another user")
        profile = db.query(Profile).filter(Profile.user_id == current_user.id).first()
        if not profile:
            return ProfileResponse(success=False, message="Profile not found")
        profile.phone_number = phone
        db.commit()
        return ProfileResponse(success=True, message="Phone updated")
